func convertSlice[T, W any](s []T, conv func(*T) (*W, error)) ([]W, error) {
	if s == nil {
		return nil, nil
	}
	out := make([]W, len(s))
	for i := range s {
		converted, err := conv(&s[i])
		if err != nil {
			return nil, fmt.Errorf("element %d: %w", i, err)
		}
		out[i] = *converted
	}
	return out, nil
}
